import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
def read(p):
    return json.loads((ROOT / p).read_text(encoding='utf-8'))
def save(p, x):
    (ROOT / p).write_text(json.dumps(x, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

