bank = {}
for path in (ROOT / 'questions').glob('q-*.json'):
    for q in json.loads(path.read_text(encoding='utf-8')):
        bank[q['id']] = q
notes = {'schema': 1, 'reviewer': 'Codex', 'at': '2026-11-07', 'sourcesChecked': [], 'reviews': []}
for qid, (url, locator, evidence, reasons, challenge) in rows.items():
    sid = f'b20-{qid}'
    source_rows = [(sid, url, locator, evidence)]
    for n, (u, loc, ev) in enumerate(extras.get(qid, []), 1):
        source_rows.append((f'{sid}-cor{n}', u, loc, ev))
    # D23 context is useful but never represented as direct support for a detail
    # missing from its synopsis. Supporting excerpts above carry the exact fact.
    if primary.get(qid):
        source_rows.append((f'{sid}-context', 'https://d23.com/a-to-z/' + primary[qid] + '/', 'Synopsis and named cast', 'Inspected official film/version and character-role context. The specific fact is established by the separately identified detailed passage.'))
    for key, u, loc, ev in source_rows:
        sources['sources'][key] = {'url': u, 'locator': loc, 'evidence': ev, 'checkedBy': 'Codex', 'checkedAt': '2026-11-07', 'timeSensitive': False, 'nextReviewAt': None, 'topics': ['Batch 20'], 'limitations': 'Text inspected; no film/video playback claimed. Wikipedia is secondary and SS is a third-party dialogue transcription. Where official summaries omit the detail, the detailed plot/dialogue passage is the evidence; general context is not claimed to prove it.'}
        notes['sourcesChecked'].append(key)
    r = by_id[qid]
    direct_sources = [x[0] for x in source_rows if not x[0].endswith('-context')]
    r.update(checks=['singleAnswer', 'context', 'wording', 'noGiveaway', 'distinctFact', 'category', 'difficulty', 'scope'],
             notes='Reviewed final stem and all four options, complete topic digests and additional cross-shard matches. ' + challenge,
             context=bank[qid]['question'] + ' Stable theatrical-film content; source limitations retained.',
             timeSensitive=False, nextReviewAt=None)
    r['premise'] = {'reason': evidence, 'sources': direct_sources}
    r['options'] = [{'basis': 'direct' if n == 0 else 'exclusive-inference', 'reason': reason, 'sources': direct_sources} for n, reason in enumerate(reasons)]
    if qid in (1053, 1077):
        for opt in r['options'][1:]:
            opt['basis'] = 'exhaustive-list'
    if qid == 1099:
        for opt in r['options'][1:]:
            opt['basis'] = 'contradiction'
    r['challenge'] = {'reviewer': 'Codex', 'at': '2026-11-07', 'premiseChecked': True, 'alternativesExcluded': True, 'notes': challenge}
    notes['reviews'].append(r)
